import { test, expect } from '@playwright/test';

test.describe('Success Toast Notification on Record Save', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should display success toast notification after saving a record', async ({ page }) => {
    // Locate and fill record name input using getByLabel
    const recordNameInput = page.getByLabel('Record Name');
    await recordNameInput.fill('Test Record');

    // Locate and fill description textarea using getByLabel
    const descriptionTextarea = page.getByLabel('Description');
    await descriptionTextarea.fill('This is a test description.');

    // Locate and click save button using getByRole
    const saveButton = page.getByRole('button', { name: 'Save Record' });
    await saveButton.click();

    // Wait for API response and toast to appear
    await page.waitForResponse(response => 
      response.url().includes('/api/records') && response.status() === 201
    );

    // Verify success toast notification is visible
    const successToast = page.getByText('Record saved successfully');
    await expect(successToast).toBeVisible();

    // Verify toast has success styling (e.g, green background)
    const toastContainer = page.locator('[data-testid="toast-container"]');
    await expect(toastContainer).toBeVisible();
    await expect(toastContainer).toHaveClass(/toast-success/);

    // Verify toast has correct duration and fades out
    await page.waitForTimeout(3000);
    await expect(successToast).not.toBeVisible();
  });

  test('should not display success toast when record save fails', async ({ page }) => {
    // Locate and fill record name input using getByLabel
    const recordNameInput = page.getByLabel('Record Name');
    await recordNameInput.fill('Invalid Record');

    // Locate and fill description textarea using getByLabel
    const descriptionTextarea = page.getByLabel('Description');
    await descriptionTextarea.fill('This record is invalid.');

    // Locate and click save button using getByRole
    const saveButton = page.getByRole('button', { name: 'Save Record' });
    await saveButton.click();

    // Wait for API response with error status
    await page.waitForResponse(response => 
      response.url().includes('/api/records') && response.status() === 400
    );

    // Verify success toast does not appear
    const successToast = page.getByText('Record saved successfully');
    await expect(successToast).not.toBeVisible();

    // Verify error toast appears instead
    const errorToast = page.getByText('Failed to save record');
    await expect(errorToast).toBeVisible();

    // Verify error toast has error styling (e.g., red background)
    const toastContainer = page.locator('[data-testid="toast-container"]');
    await expect(toastContainer).toBeVisible();
    await expect(toastContainer).toHaveClass(/toast-error/);

    // Verify error toast has correct duration and fades out
    await page.waitForTimeout(3000);
    await expect(errorToast).not.toBeVisible();
  });
});
